 static string GB(long n){return(n/1073741824.0).ToString("N1")+" GB";}static string V(Dictionary<string,object>d,string n){return d!=null&&d.ContainsKey(n)&&d[n]!=null?Convert.ToString(d[n]):"";}
 FlowLayoutPanel Card(string title){FlowLayoutPanel p=new FlowLayoutPanel();p.Dock=DockStyle.Fill;p.Margin=new Padding(4,12,4,0);p.Padding=new Padding(16);p.BackColor=Color.White;p.FlowDirection=FlowDirection.TopDown;p.WrapContents=false;p.AutoScroll=true;Label l=LabelText(p,title);l.Font=new Font("Segoe UI",13,FontStyle.Bold);return p;}
