 object Api(string path,object body){HttpWebRequest r=(HttpWebRequest)WebRequest.Create("http://127.0.0.1:"+port+path);r.Proxy=null;r.Timeout=15000;r.Headers.Add("X-Admin-Key",key);if(body!=null){r.Method="POST";r.ContentType="application/json";byte[] data=Encoding.UTF8.GetBytes(js.Serialize(body));r.ContentLength=data.Length;using(Stream stream=r.GetRequestStream())stream.Write(data,0,data.Length);}try{using(WebResponse response=r.GetResponse())using(StreamReader reader=new StreamReader(response.GetResponseStream()))return js.DeserializeObject(reader.ReadToEnd());}catch(WebException e){if(e.Response!=null)using(StreamReader reader=new StreamReader(e.Response.GetResponseStream())){Dictionary<string,object>d=js.DeserializeObject(reader.ReadToEnd())as Dictionary<string,object>;if(V(d,"error").Length>0)throw new Exception(V(d,"error"));}throw new Exception("Chưa kết nối được dịch vụ nền.");}}
 object StartEngine(){string file=Path.Combine(home,"settings.json");if(File.Exists(file))key=V(js.DeserializeObject(File.ReadAllText(file))as Dictionary<string,object>,"adminKey");try{return Api("/status",null);}catch{}ProcessStartInfo info=new ProcessStartInfo(Path.Combine(root,"runtime","node.exe"),"\""+Path.Combine(root,"server.mjs")+"\"");info.WorkingDirectory=root;info.UseShellExecute=false;info.CreateNoWindow=true;info.WindowStyle=ProcessWindowStyle.Hidden;owned=Process.Start(info);for(int i=0;i<80;i++){Thread.Sleep(150);if(owned.HasExited)throw new Exception("Dịch vụ chưa chạy được. Kiểm tra cổng đang sử dụng.");if(!File.Exists(file))continue;key=V(js.DeserializeObject(File.ReadAllText(file))as Dictionary<string,object>,"adminKey");try{return Api("/status",null);}catch{}}throw new Exception("Khởi động quá thời gian.");}
 void Work(Func<object> action,Action<object> done){if(busy)return;busy=true;BackgroundWorker w=new BackgroundWorker();w.DoWork+=delegate(object s,DoWorkEventArgs e){e.Result=action();};w.RunWorkerCompleted+=delegate(object s,RunWorkerCompletedEventArgs e){busy=false;if(e.Error!=null){note.Text=e.Error.Message;if(smoke)Environment.Exit(1);return;}done(e.Result);};w.RunWorkerAsync();}
 void RefreshStatus(){Work(delegate{return Api("/status",null);},delegate(object result){Dictionary<string,object>d=(Dictionary<string,object>)result;enabled=Convert.ToBoolean(d["enabled"]);network=Convert.ToBoolean(d["network"]);status.Text=Convert.ToBoolean(d["busy"])?"Đang kiểm tra và đồng bộ…":enabled?"Đồng bộ tự động đang bật":"Đồng bộ đang tạm dừng";toggle.Text=enabled?"Tạm dừng đồng bộ":"Bật đồng bộ";net.Text=network?"Tắt cổng đồng bộ":"Bật cổng đồng bộ";if(!storage.Focused&&storage.Text.Length==0)storage.Text=V(d,"root");if(!source.Focused&&source.Text.Length==0)source.Text=V(d,"source");Dictionary<string,object> space=d["disk"]as Dictionary<string,object>;disk.Text=space!=null?GB(Convert.ToInt64(space["free"]))+" trống":"Chưa chọn kho";Dictionary<string,object> media=d.ContainsKey("media")?d["media"]as Dictionary<string,object>:null;files.Text=media!=null?V(media,"files")+" file · "+GB(Convert.ToInt64(media["bytes"])):"0 file";peers.Items.Clear();foreach(object p in(object[])d["peers"])peers.Items.Add(V((Dictionary<string,object>)p,"url"));if(V(d,"lastError").Length>0)note.Text=V(d,"lastError");if(smoke){if(owned!=null&&!owned.HasExited)owned.Kill();Environment.Exit(0);}});}
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(!File.Exists(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"runtime","node.exe")))throw new Exception("Thiếu Node.js kèm theo. Hãy cài lại phần mềm.");if(args.Length>0&&args[0]=="--self-test")return 0;Application.Run(new Desktop(args.Length>0&&args[0]=="--smoke-test"));return 0;}catch(Exception e){MessageBox.Show(e.Message,"Kinnect Server");return 1;}}
